const tabContainer = dijit.byId('viewers');
const callback = function(viewerContainer) {
	const frame = viewerContainer.getChildren()[0].viewerFrame;
	if (frame && !frame.contentWindow.SSVCViewer) {
		frame.contentWindow.onViewerIsReady = function() {
			frame.contentWindow.SSVCViewer.displayFile();
		};
	}
};
tabContainer.selectTab(inArgs.control.tabId, callback);
